// Asumiendo que el texto viene de "Edit Fields"
const texto = $input.first().json.Respuesta_Chatbot;

// Eliminar emojis usando regex con propiedades Unicode
const textoSinEmojis = texto.replace(/\p{Extended_Pictographic}/gu, '');

// JSON.stringify() envuelve el texto en comillas y escapa TODO
const textoEnStringJson = JSON.stringify(textoSinEmojis);

// Ahora, le quitamos la primera y última comilla que stringify añade
const textoEscapado = textoEnStringJson.slice(1, -1);

// Devolvemos el texto listo para ser insertado en otro string JSON
return [{
  json: {
    // Copiamos todos los datos que ya venían
    ...$input.first().json,
    // Creamos el nuevo campo escapado
    Respuesta_Chatbot_Escapada: textoEscapado
  }
}];

